css:
.print-format { font-size: 10.5pt; }
.sla-document { line-height: 1.45; }
.sla-draft { text-align: center; color: #c00; font-weight: 700; letter-spacing: 2px; }
.sla-cover { text-align: center; }
.sla-cover p { margin: 0 0 2px; }
.sla-cover .sla-title { font-weight: 700; text-decoration: underline; font-size: 12pt; margin: 10px 0 14px; }
.sla-cover .sla-for { text-align: left; margin-bottom: 70px; }
.sla-cover .sla-between { margin-bottom: 10px; }
.sla-cover .sla-and { margin: 60px 0; }
.sla-party .sla-party-name { font-weight: 700; margin-bottom: 4px; }
.sla-page-break { page-break-after: always; }
.sla-wording table.sla-clauses { width: 100%; border-collapse: collapse; }
.sla-wording table.sla-clauses td { vertical-align: top; padding: 4px 4px; border: none; }
.sla-wording td.sla-no { white-space: nowrap; width: 5em; padding-right: 10px; }
.sla-wording tr.sla-heading td { font-weight: 700; padding-top: 12px; }
.sla-wording tr { page-break-inside: avoid; }
.sla-wording .sla-part { page-break-before: always; }
.sla-wording .sla-part-title { text-align: center; font-weight: 700; font-size: 11pt; margin: 0 0 8px; }
.sla-wording .sla-table-caption { font-style: italic; color: #1f3864; margin: 10px 0 4px; font-size: 9pt; }
.sla-wording table.sla-table { width: 100%; border-collapse: collapse; margin: 6px 0 12px; }
.sla-wording table.sla-table th, .sla-wording table.sla-table td { border: 1px solid #333; padding: 2px 5px; vertical-align: top; font-size: 9.5pt; }
.sla-wording table.sla-table th { font-weight: 700; text-align: left; }
.sla-wording .sla-right { text-align: right; }
.sla-wording .sla-center { text-align: center; }
.sla-wording .sla-signature { margin: 24px 0; page-break-inside: avoid; }
.sla-wording table.sla-signature-table { width: 100%; }
.sla-wording table.sla-signature-table td { width: 50%; padding: 4px 0; vertical-align: top; border: none; }
.sla-wording tr.sla-sign-row td { padding-top: 30px; }

html:
{%- set title = frappe.db.get_value("Contractor SLA Template", doc.sla_template, "document_title") or "SERVICE LEVEL AGREEMENT" -%}
{%- macro party(name, reg_no, address, representative, email, role) -%}
<div class="sla-party">
	<p class="sla-party-name">{{ name | e }}</p>
	{%- if reg_no %}<p>With Registration Number: {{ reg_no | e }}</p>{% endif %}
	{%- if address %}<p>Of:</p><p>{{ address | e | replace("\n", ", ") }}</p>{% endif %}
	{%- if representative %}<p>Represented By:</p><p>{{ representative | e }}</p>{% endif %}
	{%- if email %}<p>With email address:</p><p>{{ email | e }}</p>{% endif %}
	<p><i>(Hereinafter &lsquo;{{ role }}&rsquo;)</i></p>
</div>
{%- endmacro -%}
<div class="sla-document">
	{%- if doc.docstatus == 0 and not doc.sent_for_signature_on %}<p class="sla-draft">DRAFT &ndash; NOT FOR SIGNATURE</p>{% endif %}
	<div class="sla-cover">
		<p class="sla-title">{{ title | e }}</p>
		<p class="sla-for">For the {{ doc.scope_of_services | e }} at the <b>{{ doc.operation_name | e }}</b> operation of the COMPANY.</p>
		<p class="sla-between">Entered into Between:</p>
		{{ party(doc.company, doc.company_registration_no, doc.company_address, doc.company_representative, doc.company_representative_email, "the Company") }}
		<p class="sla-and">And</p>
		{{ party(doc.supplier_name or doc.supplier, doc.supplier_registration_no, doc.supplier_address, doc.supplier_representative, doc.supplier_representative_email, "the Contractor") }}
	</div>
	<div class="sla-page-break"></div>
	{{ doc.rendered_agreement or "" }}
</div>
<div id="footer-html" class="visible-pdf">
	<table class="sla-footer" style="width: 100%; font-size: 8pt; color: #555;">
		<tr>
			<td style="width: 33%; text-align: left;">Initials: ____________</td>
			<td style="width: 34%; text-align: center;">{{ doc.name }}</td>
			<td style="width: 33%; text-align: right;">Page <span class="page"></span> of <span class="topage"></span></td>
		</tr>
	</table>
</div>
